1	#!/usr/bin/env bun
2	/**
3	 * stop_on_close.ts — closing an issue an agent is working on asks that run to stop.
4	 *
5	 * ## Why closing has to mean something
6	 *
7	 * It already looked like it did. #803 was closed by hand while its run held the
8	 * in-progress label; the run kept going for five more minutes, opened a pull request,
9	 * and nothing anywhere said that closing had not stopped it. A gesture that reads as
10	 * "stop this" and does nothing is worse than no gesture, because the person walks
11	 * away believing it worked.
12	 *
13	 * ## Why a stop rather than a reopen
14	 *
15	 * Reopening would undo a decision a person just made, and the comment guard's reason
16	 * for deleting does not apply here: that guard prevents a second run from racing the
17	 * first, and closing starts no run. So the issue stays closed and the work stops —
18	 * which is what closing appeared to mean all along.
19	 *
20	 * ## Why only a person's close
21	 *
22	 * An agent closing the issue it is working on is a normal path, not an accident:
23	 * `domain/machinery/atomaton-data-pruning.ts` is built around it ("the agent closes it and the
24	 * job continues"). Stopping the run that just closed its own issue would cut it off
25	 * mid-wrap-up, so the caller passes the closer and a bot closer is no-op'd here.
26	 *
27	 * ## The mechanism is the existing one
28	 *
29	 * `/stop` is a comment carrying `STOP_TAG`, which the running job polls for — it has
30	 * to be a comment because nothing outside a job can reach into it. That works just as
31	 * well from an `issues: closed` workflow, so no second stop path exists.
32	 *
33	 * Usage:
34	 *   stop_on_close.ts --number N --closer LOGIN [--closer-type Bot|User]
35	 */
36	import { parseArgs } from "node:util";
37	import { LLM_CONTEXT_TAG, STOP_TAG } from "../../adapters/github/tags.ts";
38	import { isHumanActor } from "../../domain/work/actor.ts";
39	import { closedTheTreeNotice, stopOnCloseNotice } from "../../domain/work/closed-target.ts";
40	import { descendants, nodesToClose, nodesToStop, subtree } from "../../domain/work/work-tree.ts";
41	import { closeSubtreeUnder, readWorkTree } from "../../adapters/github/work-tree.ts";
42	import { defineScript } from "./lib/script-ref.ts";
43	
44	export interface StopOnCloseArgs {
45	  number: string | number;
46	  closer: string;
47	  "closer-type": string;
48	}
49	
50	export const ref = defineScript<StopOnCloseArgs>(import.meta.url);
51	
52	/**
53	 * The whole comment, tags included.
54	 *
55	 * `STOP_TAG` is what the running job reads; `LLM_CONTEXT_TAG` keeps this out of the
56	 * session, for the same reason `/stop`'s own notice is excluded — it is addressed to
57	 * a person, and an agent reading it would take it as something it was told.
58	 *
59	 * The tag goes on only when the root itself is running (#449). A stop tag is a request
60	 * to a job polling THIS node's thread; posted on a parent with no run of its own it
61	 * requests nothing, and — with the merged-pull-request defect — it was posted on every
62	 * close of a parent that had ever merged a pull request, saying `stop=requested` about
63	 * work nobody was doing. The descendant that IS running gets its own tag on its own
64	 * node, which is where its job is watching.
65	 */
66	export function stopOnCloseBody(args: {
67	  number: number;
68	  /** The root itself has a run in flight, as the tree read it. */
69	  rootRunning: boolean;
70	  /** The nodes under the root that were closed. */
71	  closed: readonly number[];
72	  /** The nodes under the root a stop was posted on. */
73	  stopped: readonly number[];
74	}): string {
75	  const lines = [LLM_CONTEXT_TAG.write("exclude")];
76	  if (args.rootRunning) lines.push(STOP_TAG.write("requested"));
77	  lines.push(stopOnCloseNotice(args.number, args.rootRunning), closedTheTreeNotice(args.closed, args.stopped));
78	  return lines.join("\n");
79	}
80	
81	function main(): void {
82	  const { values } = parseArgs({
83	    args: Bun.argv.slice(2),
84	    options: {
85	      number: { type: "string" },
86	      closer: { type: "string" },
87	      "closer-type": { type: "string" },
88	    },
89	  });
90	
91	  if (!values.number) {
92	    console.error("usage: stop_on_close.ts --number N --closer LOGIN [--closer-type Bot|User]");
93	    process.exit(2);
94	  }
95	
96	  const repo = process.env.GITHUB_REPOSITORY ?? "";
97	  const number = String(values.number);
98	  const closer = (values.closer ?? "").trim();
99	
100	  if (!isHumanActor(values["closer-type"])) {
101	    console.error(`#${number} was closed by a bot, which is how an agent finishes its own work. Nothing to stop.`);
102	    return;
103	  }
104	
105	  // Closing ends a line of work rather than one node, so the sub-issues and pull
106	  // requests under it go with it. See `domain/work/work-tree.ts`.
107	  //
108	  // The tree is read before anything is decided, and that ordering is the fix for what
109	  // this used to do: it read the root's label, found none, and returned — which is
110	  // right about the root and wrong about the work, because an issue can be closed with
111	  // nothing running on it and a live chain underneath.
112	  const root = Number(number);
113	  const { nodes, problems: readProblems } = readWorkTree(repo, root);
114	  // A failed read is not "nothing to do". The answer this could not determine must not
115	  // be the one that stays quiet — the rule `guard_comment_during_run.ts` follows, for
116	  // the same reason.
117	  if (nodes.length === 0) {
118	    console.error(`::error::Could not read the work under #${root}: ${readProblems.join("; ")}`);
119	    process.exit(1);
120	  }
121	
122	  const all = subtree(nodes, root);
123	  const under = descendants(all, root);
124	  const rootRunning = all.find((node) => node.number === root)?.running === true;
125	  const toStop = nodesToStop(all);
126	  const toClose = nodesToClose(under);
127	  if (toStop.length === 0 && toClose.length === 0) {
128	    console.error(`Nothing is running under #${root} and nothing under it is open. Nothing to do.`);
129	    return;
130	  }
131	
132	  const result = closeSubtreeUnder(
133	    repo,
134	    root,
135	    stopOnCloseBody({
136	      number: root,
137	      rootRunning,
138	      closed: toClose.map((n) => n.number),
139	      // The descendants only: the root is what the notice's own sentence is about, and
140	      // listing it among "runs were going on" as well would say it twice.
141	      stopped: nodesToStop(under).map((n) => n.number),
142	    }),
143	  );
144	  result.problems.push(...readProblems);
145	
146	  for (const problem of result.problems) console.error(`::warning::${problem}`);
147	  // Fatal only when the root got nothing. That comment IS the stop: without it the run
148	  // polls, finds nothing, and keeps going — while the person who closed the issue has
149	  // every reason to believe it is winding down.
150	  if (!result.rootNotified) process.exit(1);
151	
152	  console.error(
153	    `#${root} was closed by ${closer || "(unknown)"}. ` +
154	      `Stopped: ${result.stopped.map((n) => `#${n}`).join(", ") || "none"}. ` +
155	      `Closed under it: ${result.closed.map((n) => `#${n}`).join(", ") || "none"}.`,
156	  );
157	}
158	
159	if (import.meta.main) main();

