154	 * was closed; a run on it was asked to stop, which takes a moment longer and is the
155	 * part that is not done yet when this is posted.
156	 */
157	export function closedTheTreeNotice(closed: readonly number[], stopped: readonly number[]): string {
158	  const lines: string[] = [];
159	  if (closed.length > 0) {
160	    lines.push(
161	      "",
162	      `The work under it is closed too: ${closed.map((n) => `#${n}`).join(", ")}.`,
163	    );
164	  }
165	  if (stopped.length > 0) {
166	    lines.push(
167	      "",
168	      `Runs were going on ${stopped.map((n) => `#${n}`).join(", ")}, and each has been asked to stop.`,
169	    );
170	  }
171	  return lines.join("\n");
172	}
173	
174	/**
175	 * The reply to a slash command on a closed issue or pull request.
176	 *
177	 * The comment itself is left alone, unlike the in-progress guard, which deletes. That
178	 * guard deletes because the comment it caught would otherwise race a running agent and
179	 * end up in its context. Nothing is running here and nothing is racing, so removing
180	 * somebody's words would cost something and buy nothing.
181	 */
182	export function commandOnClosedNotice(
183	  commenter: string,
184	  command: string,
185	  state: TargetState,
186	  number: number,
187	): string {
188	  const what = !state.known
189	    ? `Atomaton: \`${command}\` was not run, because the state of #${number} could not be read (${state.why}), and a command is not started on a target that might be closed.`
190	    : `Atomaton: \`${command}\` was not run, because #${number} is closed.`;
191	  return [
192	    `${mentionList(commenter ? [commenter] : [])}${what}`,
193	    "",
194	    !state.known
195	      ? "Comment again once it can be read."
196	      : recoveryAdvice(state, number, command),
197	  ].join("\n");
198	}
199	
200	/** Everything the escalation below needs, gathered by the caller that was dispatching. */
201	export interface RefusedDispatch {
202	  agent: string;
203	  number: number;
204	  /** Why the dispatch was happening, in the words the dispatching caller used. */
205	  context: string;
206	  state: TargetState;
207	  /** Who asked for this run, resolved by the chain that carries the login onward. */
208	  notify: string;
209	}
210	
211	/**
212	 * The escalation posted when the machinery declines to dispatch onto a closed target.
213	 *
214	 * Written for whoever gets the mention rather than for a log, because the person
215	 * reading it did not ask for a dispatch and does not care that one was refused. What
216	 * they need is the thing that is now not going to happen, and what to do about it —
217	 * "the dispatch was rejected" is the machine's account of the same event and tells
218	 * them neither.
219	 *
220	 * Nothing retries after this. That is stated outright: a notice that leaves it open
221	 * whether something else will pick the work up is one people wait on.
222	 */
223	export function dispatchRefusedNotice(refused: RefusedDispatch): string {
224	  const { agent, number, context, state, notify } = refused;
225	  const why = !state.known
226	    ? `the state of #${number} could not be read (${state.why})`
227	    : `#${number} is closed`;
228	  return [
229	    `${mentionList(notify ? [notify] : [])}Atomaton: \`${agent}\` was not started on #${number}, because ${why}.`,
230	    "",
231	    `What was about to happen: ${context}.`,
232	    "",
233	    "Nothing will retry this.",
234	    "",
235	    !state.known
236	      ? `Start it by hand once #${number} can be read: comment \`/${agent}\` on it.`
237	      : recoveryAdvice(state, number, `/${agent}`),
238	  ].join("\n");
239	}
240	
241	/**
242	 * The notice posted when GitHub itself rejects the dispatch call (#194).
243	 *
244	 * The third way a hand-off's promise breaks, after a closed target and an
245	 * unconfirmable marker: the call to start the run failed — a bad token, a renamed
246	 * workflow, a rate limit. Nothing is running and, without this notice, nothing on the
247	 * thread would say so: the last word there would stay "a hand-off", read by every
248	 * later reader as a run working or coming.
249	 *
250	 * The advice names the command, because the state was checked open moments before the
251	 * call failed — there is no reopen step to describe, and the one thing a person can do
252	 * is start the run again by hand once the cause is gone.
253	 */
254	export function dispatchFailedNotice(failed: {
255	  agent: string;
256	  number: number;
257	  context: string;
258	  notify: string;
259	}): string {
260	  const { agent, number, context, notify } = failed;
261	  return [
262	    `${mentionList(notify ? [notify] : [])}Atomaton: \`${agent}\` was not started on #${number}, because GitHub rejected the dispatch call.`,
263	    "",
264	    `What was about to happen: ${context}.`,
265	    "",
266	    "Nothing will retry this. Start it by hand: comment `/" + agent + "` on this issue.",
267	  ].join("\n");
268	}
269	
270	/**
271	 * The notice posted when a dispatch marker never became visible in the thread.
272	 *
273	 * A different failure from a closed target, and it says so: nothing is wrong with the
274	 * issue, and the person did not do anything wrong. What happened is that GitHub did not
275	 * show the machinery its own write, so it could not tell whether another run had already
276	 * been asked for — and starting one anyway risks two runs on one node.
277	 *
278	 * The advice is to retry, because the condition is transient by nature: the thread
279	 * catches up, and the next attempt sees the marker. It names the command so the person
280	 * does not have to work out how to start the run again.
281	 */
282	export function dispatchUnconfirmedNotice(unconfirmed: {
283	  agent: string;
284	  number: number;
285	  context: string;
286	  notify: string;
287	}): string {
288	  const { agent, number, context, notify } = unconfirmed;
289	  return [
290	    `${mentionList(notify ? [notify] : [])}Atomaton: \`${agent}\` was not started on #${number}, because the dispatch could not be confirmed.`,
291	    "",
292	    `What was about to happen: ${context}.`,
293	    "",
294	    "GitHub did not show the machinery its own marker in the thread, so it could not tell whether another run had already been asked for. Starting one anyway could put two runs on this issue at once.",
295	    "",
296	    "This is usually transient. Retry shortly by commenting `/`" + agent + "` on this issue.",
297	  ].join("\n");
298	}

