344	/**
345	 * The ways a run stops itself at a limit: the clock, an iteration ceiling, the
346	 * repetition circuit breaker, or the model's context window. The tally these share
347	 * is what a person deciding between retrying and re-scoping needs; the old limit
348	 * notice named only the first three, and this comment is now the one that says it.
349	 */
350	function reachedLimit(endedBecause: string | undefined): boolean {
351	  return (
352	    endedBecause === "runtime" ||
353	    endedBecause === "iterations" ||
354	    endedBecause === "loop" ||
355	    endedBecause === "context_limit"
356	  );
357	}
358	
359	/**
360	 * How it was cut short, in the words for the person reading the comment.
361	 *
362	 * `runtime` and `iterations` are one ending to `turn.ts` — the decisions below it
363	 * turn on the same answer for either — and two different sentences here, which is
364	 * why the core's own word travels this far rather than a boolean.
365	 *
366	 * This said "ran out of iterations" for both, and the runner passes
367	 * `--max-runtime-secs` and no `--max-iterations`. So the ceiling it hits is always
368	 * the clock, and that sentence was always the wrong one.
369	 *
370	 * `context_limit` is the fourth ceiling and gets its own sentence rather than being
371	 * folded into "ran out of time": the window filled, and the way out -- a larger
372	 * `context_limit`, or a smaller task -- is different from waiting less.
373	 */
374	function howItWasCutShort(endedBecause: string | undefined): string {
375	  if (endedBecause === "stopped") return "was stopped";
376	  if (endedBecause === "loop") return "got stuck repeating itself";
377	  if (endedBecause === "failed") return "did not finish";
378	  if (endedBecause === "context_limit") return "ran out of context";
379	  return endedBecause === "iterations" ? "ran out of iterations" : "ran out of time";
380	}
381	
382	/**
383	 * The sentence that fetches a person, named by how the run actually ended.
384	 *
385	 * It used to say "task completed" whatever happened, which no one saw on a stopped
386	 * run because a stopped run rarely got a mention at all -- and the moment it did, it
387	 * was telling the person who had just stopped it that it had finished. "Review the
388	 * results" is dropped for the same reason: a run cut short may have none.
389	 *
390	 * `failed` gets its own sentence because "did not finish before it finished" is what
391	 * the cut-short wording would build from it, and because it is the one interrupted
392	 * ending whose text may be a fragment of ordinary work rather than a stop landing
393	 * between sentences.
394	 *
395	 * `no-report` is the third sentence, and it is here rather than sharing the ordinary
396	 * one because the ordinary one is the false claim this change exists to stop making.
397	 * A run that produced no closing text has no results to review; what it did is in a
398	 * saved session, and the person is being told so they can go and look.
399	 */
400	function mentionLine(
401	  ending: TurnEnding,
402	  args: { agent: string; notify?: string; endedBecause?: string },
403	): string {
404	  if (args.endedBecause === "failed") {
405	    return (
406	      `@${args.notify} — **${args.agent}** stopped mid-run, and no agent will run next. ` +
407	      `Resume it, or say what to do instead.`
408	    );
409	  }
410	  if (cutShort(args.endedBecause)) {
411	    return (
412	      `@${args.notify} — **${args.agent}** ${howItWasCutShort(args.endedBecause)} ` +
413	      `before it finished, and no agent will run next. Resume it, or say what to do instead.`
414	    );
415	  }
416	  if (ending.ended === "no-report") {
417	    return (
418	      `@${args.notify} — **${args.agent}** ended without writing a report. Nothing interrupted it ` +
419	      `and nothing runs next; it simply left no closing text, so there is nothing here to review. ` +
420	      `What it did is in its saved session.`
421	    );
422	  }
423	  return `@${args.notify} — **${args.agent}** task completed. No agent will be automatically executed next. Please review the results or provide instructions for the next step.`;
424	}
425	
426	/**
427	 * How this turn ended, as far as this comment can know.
428	 *
429	 * `succeeded` is true by construction: the workflow only runs this step when the
430	 * agent step succeeded. That is not the same as the run succeeding — a run the core
431	 * filed `failed` arrives here with the step green, which is the whole shape of #441 —
432	 * so `--ended-because` is what decides, and it carries `failed` like any other word.
433	 *
434	 * `loopLimitReached` is NOT known yet, and cannot be. The chain's own limit is
435	 * counted from the thread by `manage_dispatch_loop.ts`, which runs after this
436	 * because the tally includes the comment this is writing. Passing `false` is
437	 * therefore not a guess:
438	 *
439	 *   - it can only turn a `chain-over` into a `handed-off`, and
440	 *   - both carry the same `next`, which is the only thing read here.
441	 *
442	 * So the one signal this cannot see is the one that does not change the answer.
443	 * Deriving the ending here rather than re-deriving the parts is what removes the
444	 * two copies this file used to hold — one for the mention, one for the tag.
445	 */
446	function endingHere(args: {
447	  directive?: string;
448	  chainContinues?: string;
449	  endedBecause?: string;
450	  reported?: boolean;
451	}): TurnEnding {
452	  return endingOf({
453	    succeeded: true,
454	    endedBecause: args.endedBecause ?? "",
455	    loopLimitReached: false,
456	    chainContinues: isTrue(args.chainContinues),
457	    directive: args.directive ?? "",
458	    reported: args.reported === true,
459	  });
460	}
461	
462	/**
463	 * Whether this comment names the person nothing else will reach.
464	 *
465	 * One function because two places ask it: the comment's own mention, and the
466	 * runner's decision whether the separate "the run reached its limit" notice has
467	 * anything left to say. The limit notice used to repeat this sentence and the same
468	 * `@login` immediately after the comment that already contained it — two
469	 * notifications for one event.
470	 */
471	export function makesCompletionMention(signals: {
472	  notify?: string;
473	  directive?: string;
474	  chainContinues?: string;
475	  endedBecause?: string;
476	  reported?: boolean;
477	  agentCalledHuman?: boolean;
478	  isSubIssue?: boolean;
479	  issueClosed?: boolean;
480	}): boolean {
481	  return shouldMentionOnCompletion({
482	    ending: endingHere(signals),
483	    chainContinues: isTrue(signals.chainContinues),
484	    notify: signals.notify,
485	    agentCalledHuman: signals.agentCalledHuman === true,
486	    isSubIssue: signals.isSubIssue ?? false,
487	    issueClosed: signals.issueClosed ?? false,
488	  });
489	}
