export function stopOnPrCloseNotice(number: number, merged: boolean): string {
  const what = merged
    ? `Atomaton: #${number} was merged while an agent was working on it, so the run here has been asked to stop.`
    : `Atomaton: #${number} was closed without merging while an agent was working on it, so the run here has been asked to stop.`;
  const then = merged
    ? "The work this run was reviewing is already on the base branch, so there is nothing here left to finish — `/resume` on this pull request would review a merge that has happened."
    : "The pull request is closed but the work is not merged, so the branch and the issue it delivers still stand where they were.";
  return [
    what,
    "",
    "A close does not stop a run by itself — it kept going until this request reached it. The run stops after its current step, so it may take a minute.",
    "",
    then,
  ].join("\n");
}
```

