export function openClaimOn(repo, number): { ask; run; parked; claimed; at?: string } | undefined {
  const shaped = readComments(repo, number);
  if (shaped.openClaim === undefined) return undefined;
  const last = shaped.comments[shaped.comments.length - 1];
  const at = claimWrittenAt(shaped.comments, shaped.openClaim.ask);
  return {
    ...shaped.openClaim,
    parked: shaped.events[shaped.events.length - 1] === "waiting",
    claimed: last !== undefined && readers.claim(last.body) !== undefined,
    at,
  };
}

/** When the claim that is still open was written ... */
function claimWrittenAt(comments: readonly (ThreadEntry & {at?: string})[], ask: number): string | undefined {
  for (let i = comments.length - 1; i >= 0; i -= 1) {
    const entry = comments[i]!;
    if (entry.quoted) continue;
    const claim = readers.claim(entry.body);
    if (claim?.ask === ask) return entry.at;
  }
  return undefined;
}
```

