  // finds nothing, and keeps going.
  if (!commentOn(repo, number, stopOnPrCloseBody({ number, merged }))) {
    console.error(`::error::Could not post the stop request on #${number}`);
    process.exit(1);
  }

  console.error(
    `#${number} was ${merged ? "merged" : "closed"} while a run held it. The run has been asked to stop.`,
  );
}

